import{_ as t,o as a,c as s,ak as r}from"./chunks/framework.sV-XtlWr.js";const p=JSON.parse('{"title":"UI overview","description":"","frontmatter":{"title":"UI overview","lang":"en-US"},"headers":[],"relativePath":"ui-overview.md","filePath":"ui-overview.md","lastUpdated":1786997170000}'),o={name:"ui-overview.md"};function n(i,e,d,l,c,h){return a(),s("div",null,[...e[0]||(e[0]=[r('<h1 id="ui-overview" tabindex="-1">UI overview <a class="header-anchor" href="#ui-overview" aria-label="Permalink to &quot;UI overview&quot;">​</a></h1><p>This page is a <strong>map of the dashboard</strong> — where each view lives and what it&#39;s for. For the concepts behind a feature, follow the links to the dedicated pages (<a href="./concepts.html">Core concepts</a>, <a href="./flaky-tests.html">Flaky tests</a>, <a href="./ai-diagnosis.html">AI diagnosis &amp; clustering</a>, <a href="./reporter.html">Reporter</a>).</p><p>The dashboard is a single-page app built with <a href="https://ui.nuxt.com" target="_blank" rel="noreferrer">Nuxt UI</a>. It updates itself in real time over Server-Sent Events — pages refresh automatically when runs start or finish, so you never reload manually.</p><h2 id="inline-help" tabindex="-1">Inline help <a class="header-anchor" href="#inline-help" aria-label="Permalink to &quot;Inline help&quot;">​</a></h2><p>Blocks that aren&#39;t self-explanatory carry a small muted help icon (a circled question mark) next to their title. Click it for a short explanation and, where relevant, a <strong>Learn more</strong> link into these docs. The icon is keyboard-focusable and closes with <code>Esc</code>. Self-explanatory blocks (counters, search boxes) have no icon, keeping the UI uncluttered.</p><h2 id="open-in-ide" tabindex="-1">Open in IDE <a class="header-anchor" href="#open-in-ide" aria-label="Permalink to &quot;Open in IDE&quot;">​</a></h2><p>Every source path shown in the dashboard is clickable — hover it to reveal an <strong>open in IDE</strong> control that jumps to that file (and line) in VS Code or JetBrains. See <a href="./ide-integration.html">Open in IDE</a> for setup and the available methods.</p><h2 id="navigation" tabindex="-1">Navigation <a class="header-anchor" href="#navigation" aria-label="Permalink to &quot;Navigation&quot;">​</a></h2><p>The sidebar gives access to the top-level sections:</p><table tabindex="0"><thead><tr><th>Section</th><th>Path</th><th>Purpose</th></tr></thead><tbody><tr><td>Home</td><td><code>/</code></td><td>Aggregate stats and activity across all projects</td></tr><tr><td>Analytics</td><td><code>/analytics</code></td><td>Cross-project trends, portfolio health, and insights over a chosen time window (see <a href="./analytics.html">Analytics</a>)</td></tr><tr><td>Projects</td><td><code>/projects</code></td><td>Full project listing with search and tag filters</td></tr><tr><td>Settings</td><td><code>/settings</code></td><td>Configuration, in two groups — <strong>Instance</strong> (account, users, notifications, storage) and <strong>Analysis</strong> (AI diagnosis, wasted time, timeout hygiene, tags, pull requests)</td></tr><tr><td>Setup <em>(admins)</em></td><td><code>/setup</code></td><td>Connect the reporter, and a checklist of which optional capabilities are actually active on this instance</td></tr><tr><td>API docs</td><td><code>/docs</code></td><td>Self-contained OpenAPI 3.1 reference (no external CDN) — browse endpoints and schemas, try requests live, copy cURL / fetch snippets</td></tr><tr><td>MCP server</td><td><code>/mcp</code></td><td>Setup guide for connecting AI clients (see <a href="./mcp.html">MCP server</a>)</td></tr></tbody></table><p>Everything else is reached by drilling into a project, run, or test case:</p><table tabindex="0"><thead><tr><th>Page</th><th>Path</th></tr></thead><tbody><tr><td>Project detail</td><td><code>/projects/:id</code></td></tr><tr><td>Project edit</td><td><code>/projects/:id/edit</code></td></tr><tr><td>Test cases (project)</td><td><code>/projects/:id/test-cases</code></td></tr><tr><td>Failure cluster</td><td><code>/failure-clusters/:id</code></td></tr><tr><td>Test run</td><td><code>/test-runs/:id</code></td></tr><tr><td>Test case</td><td><code>/test-cases/:id</code></td></tr></tbody></table><h2 id="setup" tabindex="-1">Setup <a class="header-anchor" href="#setup" aria-label="Permalink to &quot;Setup&quot;">​</a></h2><p>Reachable from the sidebar at any time — not just before your first run. <strong>Administrators only</strong>, since it governs how results reach the instance and, in the desktop build, shows the local access token; when authentication is disabled every visitor is a virtual administrator, so it stays available on a default install. It carries the reporter setup steps (install, configure, run, plus <code>wrapConfig</code> and the capture fixtures under <strong>Go further</strong>) and a <strong>capability checklist</strong>: for each optional feature, whether this instance shows evidence of actually using it.</p><p>The checklist is deliberately evidence-based rather than config-based, so it answers the question an empty panel raises — <em>is this blank because it&#39;s broken, or because I never switched it on?</em> In the desktop build the page also carries the local instance&#39;s reporter URL and token, its MCP client configuration, the data location, and background-service control.</p><h2 id="home" tabindex="-1">Home <a class="header-anchor" href="#home" aria-label="Permalink to &quot;Home&quot;">​</a></h2><p>A quick health check across all projects: <strong>stats cards</strong> (projects, runs, active/passing projects, flaky count, slowest project), a <strong>test-results trend chart</strong> (pass/fail/skip/flaky over time), <strong>recent projects</strong>, and a getting-started snippet for teams that haven&#39;t wired up the reporter yet.</p><h2 id="analytics" tabindex="-1">Analytics <a class="header-anchor" href="#analytics" aria-label="Permalink to &quot;Analytics&quot;">​</a></h2><p>A cross-project decision view — where Home answers <em>&quot;what&#39;s happening now&quot;</em>, Analytics answers <em>&quot;across projects, over time&quot;</em>. A <strong>scope bar</strong> at the top sets the period (last 7 / 30 / 90 days, last year, or all time), an optional environment, and a full-runs-only toggle; every widget re-aggregates against that scope.</p><p>Widgets are grouped into four bands, in reading order:</p><ul><li><strong>Where things stand</strong> — portfolio health, the insights feed, the pass-rate heatmap.</li><li><strong>Where the pain is</strong> — open failure clusters, the flakiest-tests leaderboard, wasted CI time.</li><li><strong>Which way it is going</strong> — regression velocity, CI time.</li><li><strong>Detail</strong> — the browser matrix, cross-project slow endpoints.</li></ul><p><a href="./timeline-markers.html">Timeline markers</a> overlay your deploys and infrastructure changes on the trend charts.</p><p>See <a href="./analytics.html">Analytics</a> for what each widget answers and how the periods are compared.</p><h2 id="projects" tabindex="-1">Projects <a class="header-anchor" href="#projects" aria-label="Permalink to &quot;Projects&quot;">​</a></h2><p>The primary hub: instant <strong>text search</strong>, <strong>tag filters</strong>, and a table showing each project&#39;s run count, last-run date, duration, status, test pass/fail bar, report links, and actions. Create a project manually with <strong>New project</strong> (it&#39;s also created automatically on first result submission).</p><h2 id="project-detail" tabindex="-1">Project detail <a class="header-anchor" href="#project-detail" aria-label="Permalink to &quot;Project detail&quot;">​</a></h2><p>The complete history for one project, organized into tabs:</p><ul><li><strong>Test runs</strong> — every run with status, start time, duration, test counts, and browser badges; select two runs to compare. Runs with a shared failure signature roll up into <strong>Failure clusters</strong> here (see <a href="./ai-diagnosis.html">AI diagnosis &amp; clustering</a>).</li><li><strong>Flaky tests</strong> — intermittent tests scored by a composite flakiness metric, with root-cause classification and impact ranking. See <a href="./flaky-tests.html#flaky-test-detection">Flaky tests</a>.</li><li><strong>Performance</strong> — average/P90 duration trends and a slowest-tests table. See <a href="./flaky-tests.html#performance">Performance</a>.</li><li><strong>Test cases</strong> — every unique test with status, executed-only pass rate, result breakdown, average duration, and last run; searchable, filterable by status, <a href="./reporter.html#test-tags">tag</a>, owner, priority and last-run age (stale cases hidden by default), paginated, with flat and per-spec tree views.</li><li><strong>Compare</strong> — side-by-side delta between two runs (new failures, recovered, duration changes).</li><li><strong>Spec health</strong> — a heatmap grouping test cases by spec file and coloring each by pass rate, so an unhealthy area of the suite jumps out. See <a href="./flaky-tests.html#spec-health-heatmap">Spec health heatmap</a>.</li><li><strong>Quarantine</strong> — tests excluded from the <a href="./ci.html#blocking-a-merge">CI gate</a>&#39;s verdict while still running, each with its passing streak and whether it has earned a release, plus the debt the list represents. See <a href="./flaky-tests.html#quarantine-with-a-way-out">Quarantine</a>.</li><li><strong>AI steps</strong> — liveness for the committed <a href="./ai-steps.html">AI-step artifacts</a> this project replays: which prompts are exercised by recent runs, and which have gone dormant.</li><li><strong>Members</strong> <em>(admins, when auth is enabled)</em> — grant or scope project access per user. See <a href="./authentication.html#project-access">Project access</a>.</li></ul><p>Project <strong>edit</strong> (<code>/projects/:id/edit</code>) sets the label, description, tags, per-project SCM token, and <strong>AI diagnosis instructions</strong> (project-specific context combined with the global instructions for every diagnosis).</p><p>Project <strong>import</strong> (<code>/projects/:id/import</code>, admins only) backfills runs recorded before you adopted Piwi from Playwright blob reports, checking each archive against the server&#39;s size limit and the project&#39;s existing imports before uploading anything. See <a href="./importing-runs.html">Importing past runs</a>.</p><h2 id="test-run-detail" tabindex="-1">Test run detail <a class="header-anchor" href="#test-run-detail" aria-label="Permalink to &quot;Test run detail&quot;">​</a></h2><p>A deep dive into a single run. The <strong>summary header</strong> shows status, duration, test counts, duration metrics (avg/P90), and metadata cards (CI/environment, source control, tags). While a run is still <code>running</code>, a <strong>live progress bar</strong> and streaming results appear in real time, and a <strong>Live activity</strong> strip shows the step each worker is on right now. <strong>Reports</strong> buttons open or download the attached HTML reports (Playwright, Monocart).</p><p>The right panel is tabbed:</p><ul><li><strong>Test cases</strong> — every test with browser icon, status, duration, location, errors, annotations, and traces; searchable, filterable by status/browser, and grouped by suite hierarchy (describe blocks).</li><li><strong>Insights</strong> — what changed versus the last passing baseline: new regressions, recurring failures, fixed tests, new flaky tests, performance changes, worker imbalance, and new clusters. See <a href="./flaky-tests.html#run-insights">Run insights</a>.</li><li><strong>Failure groups</strong> — failures grouped by error fingerprint, each with flaky/worker-correlation signals and actions to filter the list, trigger AI diagnosis, or open the cluster. See <a href="./ai-diagnosis.html">AI diagnosis &amp; clustering</a>.</li><li><strong>Regression</strong> <em>(shown when a baseline exists)</em> — the regression delta for this run at a glance.</li><li><strong>Timeline</strong> — a horizontal per-worker timeline of test execution, with a span-type filter to isolate test phases (setup, actual test, wasted waits, teardown); click a bar to jump to that test case.</li><li><strong>Compare</strong> — pick a baseline run for a side-by-side delta (improved / regressed / unchanged).</li><li><strong>Slow endpoints</strong> — network requests grouped by method + normalized route, with avg/p90/max duration and error rate. Requires the <a href="./capture-fixtures.html">capture fixtures</a>.</li></ul><p>Administrators can <strong>delete</strong> the entire run and its files from the header.</p><h2 id="test-case-detail" tabindex="-1">Test case detail <a class="header-anchor" href="#test-case-detail" aria-label="Permalink to &quot;Test case detail&quot;">​</a></h2><p>Two pages live under this heading, and <a href="./concepts.html#execution">Core concepts</a> draws the line between them: an <strong>execution</strong> (<code>/test-run-cases/:id</code>) answers <em>&quot;why did this attempt fail?&quot;</em>, and a <strong>test case</strong> (<code>/test-cases/:id</code>) answers <em>&quot;how has this test behaved over time?&quot;</em>. Most links from a run land on an execution; the test&#39;s title links to the test case above it.</p><p>A failing execution opens diagnosis-first: the error, a verdict, the cluster it belongs to, and an evidence funnel running from the call stack down to the ARIA snapshot — deeper still when a trace is attached. All of it, plus the bundled trace viewer, is described in <a href="./evidence.html">Failure evidence</a>. The summary shows one chip per <strong>attempt</strong> (with its outcome and duration) when a test retried, so &quot;how did this execution get here&quot; is answerable at a glance.</p><h2 id="failure-cluster-detail" tabindex="-1">Failure cluster detail <a class="header-anchor" href="#failure-cluster-detail" aria-label="Permalink to &quot;Failure cluster detail&quot;">​</a></h2><p>Each cluster (<code>/failure-clusters/:id</code>) opens on a summary — signature, affected tests, and <strong>Triage</strong> (set status open/resolved/ignored and write a note) — above a two-column body. Once a fix has landed the summary also carries the <strong>resolution</strong>: which verdict the runs support, the run and commit it landed in, and how long the cluster stayed open. See <a href="./ai-diagnosis.html#did-the-fix-work">Did the fix work?</a>. The left column collapses each investigation section to a header with an at-a-glance peek (click to expand, and the state is remembered): the raw <strong>error message</strong>, an <strong>alternative-locators</strong> panel for broken locators, <strong>test evidence</strong> (one tab per affected case, each linking through to its test-run case, with screenshots, traces, failing steps, console/network signals and source), and <strong>what changed</strong> (the SCM diff since the last green run, with a baseline-commit picker and commit browser). The right column holds the <strong>AI diagnosis</strong> — an SCM-grounded LLM analysis whose cited evidence links back to the matching left-column section. Full detail: <a href="./ai-diagnosis.html">AI diagnosis &amp; clustering</a>.</p><h2 id="offline-export" tabindex="-1">Offline export <a class="header-anchor" href="#offline-export" aria-label="Permalink to &quot;Offline export&quot;">​</a></h2><p>An <strong>Export</strong> button on a test-case execution (<code>/test-run-cases/:id</code>) and on a failure cluster (<code>/failure-clusters/:id</code>) writes the investigation to an HTML, ZIP, PDF, Markdown or JSON file that opens with no network and no Piwi server. See <a href="./offline-export.html">Offline export</a>.</p><h2 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Page</th><th>Path</th><th>What it does</th></tr></thead><tbody><tr><td>General</td><td><code>/settings</code></td><td>Basic app configuration; a <strong>Reset Demo</strong> button in demo mode</td></tr><tr><td>Account</td><td><code>/settings/account</code></td><td>Your display name, email, password, and <strong>connected accounts</strong> (link/unlink Google or GitHub — see <a href="./authentication.html#oauth-google-github">OAuth</a>)</td></tr><tr><td>Users</td><td><code>/settings/users</code></td><td>User accounts, roles, project access, and API keys (shown once, stored hashed) — see <a href="./authentication.html">Authentication</a></td></tr><tr><td>Storage</td><td><code>/settings/storage</code></td><td>Storage stats and cleanup (bulk-delete runs older than N days) — see <a href="./storage.html#storage-management">Storage</a></td></tr><tr><td>Tags</td><td><code>/settings/tags</code></td><td>Create, color, edit, and delete the tags used to organize projects</td></tr><tr><td>Pull requests</td><td><code>/settings/pr-feedback</code></td><td>What Piwi posts back to a pull request when a run finishes — see <a href="./ci.html#pull-request-feedback">Pull-request feedback</a></td></tr><tr><td>Performance</td><td><code>/settings/performance</code></td><td>Wasted-time patterns (which Playwright waits count as &quot;wasted time&quot;) and timeout-hygiene thresholds (oversized per-test timeouts, stale <code>test.slow()</code> marks) — see <a href="./configuration.html#wasted-time">Configuration</a></td></tr><tr><td>AI</td><td><code>/settings/ai</code></td><td>Provider/model roles, auto-diagnose, global instructions, and context limits — see <a href="./ai-diagnosis.html#enabling-ai-diagnosis">AI diagnosis</a></td></tr><tr><td>Notifications</td><td><code>/settings/notifications</code></td><td>Channels, subscriptions, and SMTP — see <a href="./notifications.html">Notifications &amp; alerts</a></td></tr></tbody></table><p>Where an environment variable backs a setting, the field is shown read-only with a lock badge and the env var name (see <a href="./configuration.html">Configuration</a>).</p><h2 id="real-time-updates" tabindex="-1">Real-time updates <a class="header-anchor" href="#real-time-updates" aria-label="Permalink to &quot;Real-time updates&quot;">​</a></h2><p>The dashboard uses Server-Sent Events so it never needs a manual refresh:</p><ul><li><strong>Global stream</strong> (<code>/api/stream</code>) — tells every connected client when a run starts, finishes, or is submitted; pages re-fetch their data.</li><li><strong>Per-run stream</strong> (<code>/api/test-runs/:id/stream</code>) — drives the live progress on the run detail page during a streaming run.</li></ul><h2 id="live-demo" tabindex="-1">Live demo <a class="header-anchor" href="#live-demo" aria-label="Permalink to &quot;Live demo&quot;">​</a></h2><p>The <a href="https://piwitests.github.io/demo/" target="_blank" rel="noreferrer">live demo</a> runs entirely in your browser (in-memory SQLite) and adds two things the real app doesn&#39;t need:</p><p><strong>Simulate a test run</strong> — the demo banner replays the exact streaming protocol a Piwi reporter speaks during a real run, so you can watch one arrive live. Scenarios: a passing run, a run with failures (joining a known cluster plus a brand-new one), flaky retries, a performance regression, an interrupted run, and a cross-browser run. Each creates a real run in the in-browser database, so worker timeline, failure groups, and history comparisons all behave exactly as they would against a server.</p><p><strong>Acting as</strong> — the demo runs with authentication conceptually enabled. Switch between pre-seeded identities (an admin, a CI reporter, and several project-scoped users) to see how <a href="./authentication.html#project-access">project access</a> changes what each user sees. Acting as the admin, you can change affectations live and then switch users to see the effect.</p><h2 id="responsive-dark-mode" tabindex="-1">Responsive &amp; dark mode <a class="header-anchor" href="#responsive-dark-mode" aria-label="Permalink to &quot;Responsive &amp; dark mode&quot;">​</a></h2><p>The dashboard is fully responsive — sidebar navigation on desktop, collapsible sidebar and horizontally scrolling tables on tablet, and a stacked/hamburger layout on mobile. It supports light and dark themes, following the system preference by default, with a manual toggle in the sidebar.</p>',54)])])}const g=t(o,[["render",n]]);export{p as __pageData,g as default};
